
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_tm_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_tm", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.654653062750740e+00, -4.561985080887443e+00, -4.432201251028443e+00, -4.252559238412083e+00, -4.008075028955220e+00, -3.683330230349293e+00, -3.266719512805995e+00, -2.757977130278488e+00, -2.177473575386859e+00, -1.568426088237897e+00, -1.011346150655688e+00, -7.092538878734771e-01, -5.994134892565055e-01, -5.077395235762386e-01, -3.666094132772121e-01, -2.263412032355360e-01, -1.198042122474565e-01, -5.402436563089785e-02, -2.012346727084225e-02, -5.340788263075082e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


